"""Shared plan-guard policy: generated planner plan files are never edited by hand."""
from __future__ import annotations

import fnmatch
import os
import re
from pathlib import Path

MESSAGE = "generated by plan.py — change JSON through plan.py"
_UNIT_BRIEF = "phases/*/*/U*/brief.json"
_PATCH_HEADER = re.compile(r"^\*\*\* (?:Add|Update|Delete) File: (.+?)\s*$", re.MULTILINE)
_MAX_CANDIDATE = 500


def generated_plan_file(path: str, cwd: str) -> str | None:
    """Return the plan directory when ``path`` is a generated file under one, else None."""
    if not isinstance(path, str) or not path or "\n" in path or len(path) > _MAX_CANDIDATE:
        return None
    absolute = Path(path) if os.path.isabs(path) else Path(cwd or os.getcwd()) / path
    absolute = Path(os.path.normpath(absolute))
    for directory in absolute.parents:
        if not (directory / "plan.json").is_file():
            continue
        parts = absolute.relative_to(directory).parts
        relative = "/".join(parts)
        if (parts[0] == "views" and len(parts) > 1
                or parts[0] == "context" and len(parts) > 1
                or len(parts) == 5 and fnmatch.fnmatchcase(relative, _UNIT_BRIEF)):
            return str(directory)
    return None


def candidate_paths(tool_input) -> list[str]:
    """Path-like strings of a tool input: ``file_path``/``path`` values and apply_patch headers."""
    found: list[str] = []

    def walk(value):
        if isinstance(value, str):
            found.extend(match.group(1) for match in _PATCH_HEADER.finditer(value))
            if "\n" not in value and len(value) <= _MAX_CANDIDATE:
                found.append(value)
        elif isinstance(value, dict):
            for item in value.values():
                walk(item)
        elif isinstance(value, (list, tuple)):
            for item in value:
                walk(item)

    walk(tool_input)
    return found


def plan_guard_hit(tool_input, cwd: str) -> str | None:
    """First generated plan file touched by a tool input, or None."""
    for candidate in candidate_paths(tool_input):
        if generated_plan_file(candidate, cwd):
            return candidate
    return None
